public SqliteHostStorePersistence(Path database) {
    try {
        connection = DriverManager.getConnection("jdbc:sqlite:" + database.toAbsolutePath().normalize());
        try (Statement statement = connection.createStatement()) {
            statement.execute("PRAGMA journal_mode=WAL");
            statement.execute("PRAGMA synchronous=FULL");
            statement.execute("PRAGMA busy_timeout=5000");
            statement.execute("PRAGMA foreign_keys=ON");
            statement.execute("""
                    CREATE TABLE IF NOT EXISTS ji_host_sessions (
                      session_id TEXT PRIMARY KEY,
                      storage_revision INTEGER NOT NULL CHECK (storage_revision >= 0),
                      session_revision INTEGER NOT NULL CHECK (session_revision >= 0),
                      created_at TEXT NOT NULL,
                      working_directory TEXT NOT NULL,
                      name TEXT,
                      updated_at TEXT NOT NULL,
                      document BLOB NOT NULL,
                      accepted_seq INTEGER NOT NULL CHECK (accepted_seq >= 0),
                      event_seq INTEGER NOT NULL CHECK (event_seq >= 0),
                      snapshot_revision INTEGER NOT NULL CHECK (snapshot_revision >= 0),
                      snapshot_base_event_seq INTEGER NOT NULL CHECK (snapshot_base_event_seq >= 0),
                      snapshot_payload BLOB NOT NULL,
                      snapshot_created_at TEXT NOT NULL DEFAULT '1970-01-01T00:00:00Z',
                      queue_json BLOB NOT NULL,
                      commands_json BLOB NOT NULL,
                      state_commands_json BLOB NOT NULL DEFAULT '{}',
                      events_json BLOB NOT NULL,
                      acknowledgements_json BLOB NOT NULL DEFAULT '{}',
                      composer_json BLOB NOT NULL,
                      active_run_json BLOB
                    )
                    """);
            try {
                statement.execute("ALTER TABLE ji_host_sessions ADD COLUMN snapshot_created_at TEXT NOT NULL DEFAULT '1970-01-01T00:00:00Z'");
            } catch (SQLException alreadyMigrated) {
                String message = alreadyMigrated.getMessage();
                if (message == null || !message.toLowerCase(java.util.Locale.ROOT).contains("duplicate column")) {
                    throw alreadyMigrated;
                }
            }
            try {
                statement.execute("ALTER TABLE ji_host_sessions ADD COLUMN state_commands_json BLOB NOT NULL DEFAULT '{}'");
            } catch (SQLException alreadyMigrated) {
                String message = alreadyMigrated.getMessage();
                if (message == null || !message.toLowerCase(java.util.Locale.ROOT).contains("duplicate column")) {
                    throw alreadyMigrated;
                }
            }
            try {
                statement.execute("ALTER TABLE ji_host_sessions ADD COLUMN acknowledgements_json BLOB NOT NULL DEFAULT '{}'");
            } catch (SQLException alreadyMigrated) {
                String message = alreadyMigrated.getMessage();
                if (message == null || !message.toLowerCase(java.util.Locale.ROOT).contains("duplicate column")) {
                    throw alreadyMigrated;
                }
            }
            statement.execute("""
                    CREATE INDEX IF NOT EXISTS ji_host_sessions_summary_page
                    ON ji_host_sessions(working_directory, updated_at DESC, session_id ASC)
                    """);
            statement.execute("""
                    CREATE INDEX IF NOT EXISTS ji_host_sessions_summary_page_all
                    ON ji_host_sessions(updated_at DESC, session_id ASC)
                    """);
            statement.execute("""
                    CREATE TABLE IF NOT EXISTS ji_host_timeline (
                      session_id TEXT NOT NULL REFERENCES ji_host_sessions(session_id) ON DELETE CASCADE,
                      sequence INTEGER NOT NULL CHECK (sequence >= 1),
                      message_json BLOB NOT NULL,
                      PRIMARY KEY(session_id, sequence)
                    ) WITHOUT ROWID
                    """);
            statement.execute("""
                    CREATE TABLE IF NOT EXISTS ji_host_timeline_state (
                      session_id TEXT PRIMARY KEY
                        REFERENCES ji_host_sessions(session_id) ON DELETE CASCADE,
                      generation INTEGER NOT NULL CHECK (generation >= 1)
                    ) WITHOUT ROWID
                    """);
            statement.execute("""
                    CREATE TABLE IF NOT EXISTS ji_host_create_session_commands (
                      command_id TEXT PRIMARY KEY,
                      payload_hash TEXT NOT NULL,
                      session_id TEXT NOT NULL REFERENCES ji_host_sessions(session_id) ON DELETE RESTRICT
                    ) WITHOUT ROWID
                    """);
            statement.execute("""
                    CREATE TABLE IF NOT EXISTS ji_host_result_refs (
                      result_ref TEXT PRIMARY KEY,
                      session_id TEXT NOT NULL REFERENCES ji_host_sessions(session_id) ON DELETE CASCADE
                    )
                    """);
            statement.execute("""
                    CREATE TABLE IF NOT EXISTS ji_host_metadata (
                      key TEXT PRIMARY KEY,
                      value INTEGER NOT NULL CHECK (value >= 0)
                    )
                    """);
            statement.execute("""
                    INSERT OR IGNORE INTO ji_host_metadata(key, value) VALUES ('search_revision', 0)
                    """);
            statement.execute("""
                    CREATE VIRTUAL TABLE IF NOT EXISTS ji_host_search USING fts5(
                      session_id UNINDEXED,
                      entry_id UNINDEXED,
                      content,
                      role UNINDEXED,
                      tokenize='unicode61'
                    )
                    """);
        }
    } catch (SQLException exception) {
        throw storage("cannot open SQLite HostStore", exception);
    }

